ruleEntry.formula:
AND( 
    ISPICKVAL(Region_Flag__c, "Bahrain"), 
    OR( 
        AND( 
            ISPICKVAL(Type, "Benefit"), 
            OR( 
                AND( 
                    ISPICKVAL(Sub_Type__c, "ATM"), 
                    OR( 
                        ISPICKVAL(cc_Request_Type__c, "Financial Impact - Fraudulent / Unauthorized"), 
                        ISPICKVAL(cc_Request_Type__c, "No Financial Impact - Fraudulent/Unauthorized") 
                    ) 
                ), 
                AND( 
                    ISPICKVAL(Sub_Type__c, "POS / E-Commerce"), 
                    OR(  
                        ISPICKVAL(cc_Request_Type__c, "Financial Impact - Fraudulent / Unauthorized"), 
                        ISPICKVAL(cc_Request_Type__c, "No Financial Impact - Fraudulent/Unauthorized") 
                    ) 
                ) 
            ) 
        ), 
        AND( 
            ISPICKVAL(Type, "MasterCard"), 
            OR( 
                AND( 
                    ISPICKVAL(Sub_Type__c, "ATM"), 
                    OR( 
                        ISPICKVAL(cc_Request_Type__c, "Financial Impact - Fraudulent / Unauthorized"), 
                        ISPICKVAL(cc_Request_Type__c, "No Financial Impact - Fraudulent/Unauthorized") 
                    ) 
                ), 
                AND( 
                    ISPICKVAL(Sub_Type__c, "POS / E-Commerce"), 
                    OR( 
                        ISPICKVAL(cc_Request_Type__c, "Financial Impact - Fraudulent / Unauthorized"), 
                        ISPICKVAL(cc_Request_Type__c, "No Financial Impact - Fraudulent/Unauthorized") 
                    ) 
                ) 
            ) 
        ) 
    ) 
)

OR(

/* Account Faults */
AND(
    ISPICKVAL(Type, "Account Faults"),
    OR(
        AND(
            ISPICKVAL(Sub_Type__c, "Account Reactivation Issues"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Post relationship termination"),
                ISPICKVAL(cc_Request_Type__c, "Post Alburaq termination"),
                ISPICKVAL(cc_Request_Type__c, "Post ila termination")
            )
        ),
        AND(
            ISPICKVAL(Sub_Type__c, "Account Settings Issues"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Enable/Disable Interest"),
                ISPICKVAL(cc_Request_Type__c, "IBAN Letter Issuance")
            )
        ),
								AND(
            ISPICKVAL(Sub_Type__c, "Account Creation Failure"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Fx accounts"),
                ISPICKVAL(cc_Request_Type__c, "Fixed Deposit/Wakala"),
																ISPICKVAL(cc_Request_Type__c, "Alkanz"),
																ISPICKVAL(cc_Request_Type__c, "Jamiya")
            )
        ),
        ISPICKVAL(Sub_Type__c, "Account termination fault"),

        /* Profile Settings Faults */
        AND(
            ISPICKVAL(Sub_Type__c, "Profile Settings Faults"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Update Mobile Number"),
                ISPICKVAL(cc_Request_Type__c, "Switch Profile (ila/Alburaq)")
            )
        )
    )
),

/* Login Failure */
AND(
    ISPICKVAL(Type, "Login Failure"),
    OR(
        ISPICKVAL(Sub_Type__c, "Email Validation"),
        ISPICKVAL(Sub_Type__c, "ID & Verification"),
        ISPICKVAL(Sub_Type__c, "PIN Creation"),
        ISPICKVAL(Sub_Type__c, "Credential Errors")
    )
),

/* Card Faults */
AND(
    ISPICKVAL(Type, "Card Faults"),
    OR(
        AND(
            ISPICKVAL(Sub_Type__c, "Premium"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Upgrade issue"),
                ISPICKVAL(cc_Request_Type__c, "Downgrade issue")
            )
        ),
		AND(
            ISPICKVAL(Sub_Type__c, "Debit Card Order/Activation Failure"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Debit Card Order"),
                ISPICKVAL(cc_Request_Type__c, "Debit Card Activation")
            )
        ),
        AND(
            ISPICKVAL(Sub_Type__c, "Rewards Issues"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Earning Points issue"),
                ISPICKVAL(cc_Request_Type__c, "Redeem Tokens issue"),
                ISPICKVAL(cc_Request_Type__c, "Switch Reward Type issue"),
                ISPICKVAL(cc_Request_Type__c, "Link Airmiles membership issue")
            )
        ),
        ISPICKVAL(Sub_Type__c, "Tokenization Issues"),
        AND(
            ISPICKVAL(Sub_Type__c, "Transaction Issues"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Unclear response code"),
                ISPICKVAL(cc_Request_Type__c, "Transaction OTP Fault"),
                ISPICKVAL(cc_Request_Type__c, "Transaction attempt not found")
            )
        ),
        AND(
            ISPICKVAL(Sub_Type__c, "Credit Card Application/Activation Failure"),
            OR(
                ISPICKVAL(cc_Request_Type__c, "Credit Card Application"),
                ISPICKVAL(cc_Request_Type__c, "Credit Card Activation")
            )
        )
    )
),


/* Fees & Charges/Interest */
AND(
    ISPICKVAL(Type, "Fees & Charges/Interest"),
    OR(
        ISPICKVAL(Sub_Type__c, "Incorrect fees & charges applied"),
        ISPICKVAL(Sub_Type__c, "Credit Card Interest calculation")
    )
)

)
